import subprocess, re, math, json

def git(*args):
    return subprocess.check_output(["git", "-c", "safe.directory=/app/dclm", *args])

obj_paths = {}
for line in git("rev-list", "--all", "--objects").decode("utf-8", "replace").splitlines():
    parts = line.split(" ", 1)
    if len(parts) == 2:
        obj_paths.setdefault(parts[0], set()).add(parts[1])

all_objs = git("cat-file", "--batch-check=%(objectname) %(objecttype) %(objectsize)", "--batch-all-objects").decode("utf-8", "replace").splitlines()

def shannon_entropy(s):
    if not s:
        return 0.0
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1
    n = len(s)
    return -sum((c/n) * math.log2(c/n) for c in freq.values())

# 1. Inspect all dcnlp_diff contents across all JSON blobs
print("=== Checking all dcnlp_diff fields ===")
seen_diffs = set()
for line in all_objs:
    sha, otype, _ = line.split()
    if otype != "blob":
        continue
    paths = sorted(obj_paths.get(sha, []))
    if any(p.endswith(".json") for p in paths):
        raw = git("cat-file", "blob", sha).decode("utf-8", "replace")
        if "dcnlp_diff" in raw:
            try:
                data = json.loads(raw)
                diffs = []
                def collect(obj):
                    if isinstance(obj, dict):
                        for k, v in obj.items():
                            if k == "dcnlp_diff" and v:
                                diffs.append(v)
                            else:
                                collect(v)
                    elif isinstance(obj, list):
                        for item in obj:
                            collect(item)
                collect(data)
                for d in diffs:
                    if d not in seen_diffs:
                        seen_diffs.add(d)
                        print(f"--- JSON {paths} (len={len(d)}) ---")
                        for dline in d.splitlines():
                            if any(w in dline.lower() for w in ["key", "token", "secret", "pass", "cred", "auth", "login", "akia", "hf_", "ghp_", "wandb", "openai", "bashrc", "export"]):
                                print("  ", dline[:200])
            except Exception as e:
                print(f"JSON parse err {paths}: {e}")
'

python3 -c '
import subprocess, re, math

def git(*args):
    return subprocess.check_output(["git", "-c", "safe.directory=/app/dclm", *args])

obj_paths = {}
for line in git("rev-list", "--all", "--objects").decode("utf-8", "replace").splitlines():
    parts = line.split(" ", 1)
    if len(parts) == 2:
        obj_paths.setdefault(parts[0], set()).add(parts[1])

all_objs = git("cat-file", "--batch-check=%(objectname) %(objecttype) %(objectsize)", "--batch-all-objects").decode("utf-8", "replace").splitlines()

def entropy(s):
    freq = {}
    for c in s:
        freq[c] = freq.get(c, 0) + 1
    n = len(s)
    return -sum((v/n)*math.log2(v/n) for v in freq.values())

hex40 = re.compile(r"^[0-9a-f]{40}$")
hex32 = re.compile(r"^[0-9a-f]{32}$")
hex64 = re.compile(r"^[0-9a-f]{64}$")
uuid_rx = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$", re.I)
tok_rx = re.compile(r"[A-Za-z0-9+/=_-]{20,}")

seen = set()
for line in all_objs:
    sha, otype, _ = line.split()
    if otype != "blob":
        continue
    paths = sorted(obj_paths.get(sha, []))
    if any(p.endswith((".tiktoken", ".png", ".jpg", ".pdf", ".svg")) for p in paths):
        continue
    text = git("cat-file", "blob", sha).decode("utf-8", "replace")
    for m in tok_rx.finditer(text):
        s = m.group(0)
        if len(s) > 80:
            continue
        if hex40.match(s) or hex32.match(s) or hex64.match(s) or uuid_rx.match(s):
            continue
        # skip snake_case identifiers with underscores >= 2 unless starts with hf_/ghp_/sk_/etc.
        if s.count("_") >= 2 and not s.lower().startswith(("hf_", "gh", "github_pat_", "sk_")):
            continue
        if s.count("-") >= 2 and not s.lower().startswith(("sk-", "xox")):
            continue
        e = entropy(s)
        has_upper = any(c.isupper() for c in s)
        has_lower = any(c.islower() for c in s)
        has_digit = any(c.isdigit() for c in s)
        if (e >= 4.2 and ((has_upper and has_lower and has_digit) or (has_lower and has_digit and len(s) >= 30))) or s.lower().startswith(("akia", "asia", "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "hf_")):
            if (s, tuple(paths)) not in seen:
                seen.add((s, tuple(paths)))
                ctx = text[max(0, m.start()-35):min(len(text), m.end()+35)].replace("\n", "\\n")
                print(f"{paths} | tok={s!r} (H={e:.2f}) | ctx={ctx!r}")
'

